    }

pub fn finalize(self: *@This()) void {
            _ = self.deref();
    }
    const AsyncJob = struct {
    
    pub fn runTask(task: *jsc.WorkPoolTask) void {
                const target: *T = @fieldParentPtr("task", task);
                _ = AsyncJob.run(target);
        }
    
    pub fn run(self: *@This()) void {
                const globalThis: *jsc.JSGlobalObject = self.globalThis;
                const vm = globalThis.bunVMConcurrently();
                _ = self.stream.doWork();
                _ = vm.enqueueTaskConcurrent(jsc.ConcurrentTask.create(jsc.Task.init(self)));
        }
    };
};
}
